insert into public.vocabulary_items
(vocabulary_id,term,part_of_speech,core_meaning,senses,word_family,collocations,status)
values
('vocab_develop','develop','verb','to grow or change into something bigger, stronger or more advanced, or to make something do this','[{"senseId":"develop_1","meaning":"to grow or change into something bigger, stronger or more advanced, or to make something do this","acceptedParaphrases":["build up","improve over time"],"masteryContexts":[{"contextId":"u10_41_develop_meaning","text":"Team sports help children develop confidence and social skills.","meaning":"to make a skill grow stronger","wrongMeanings":["to make a skill weaker","to hide a skill from others","to test a skill once"]},{"contextId":"u10_41_develop_paraphrase","text":"The company plans to develop an app that helps students learn new words.","meaning":"to create something new over time","wrongMeanings":["to sell something old","to repair something broken","to ban something completely"]}],"situationDistractors":["A boy stopped practising the guitar and forgot how to play.","A town closed its library and shrank to half its size.","A girl kept writing her essays in exactly the same way for years.","A boy stopped going to piano lessons and forgot how to play.","A girl’s handwriting stayed exactly the same for years.","A shop got smaller and smaller until it closed."],"gapDistractors":[{"contextId":"u10_41_develop_gap_1","answer":"develop","wrong":["succeed","reflect","contribute"]},{"contextId":"u10_41_develop_gap_2","answer":"develop","wrong":["succeed","reflect","contribute"]},{"contextId":"u10_41_develop_gap_3","answer":"develop","wrong":["succeed","encourage","reflect"]}],"spellingErrors":["develope","devellop","devlop","developp","divelop","develup"],"wordFamilyForms":[{"form":"develop","partOfSpeech":"verb","example":"The course helps students develop their writing.","pedagogicallyUseful":true},{"form":"development","partOfSpeech":"noun","example":"The early years are important for a child’s development.","pedagogicallyUseful":true,"altExample":"Reading helps the development of a child’s imagination."},{"form":"developed","partOfSpeech":"adjective","example":"Children in developed countries usually stay at school until eighteen.","pedagogicallyUseful":true,"altExample":"Her writing style is now more developed and mature."}],"masteryPassages":[{"passageId":"u10_41_develop_passage_1","contextId":"u10_41_develop_gap_1","text":"Joining the debate club helped Raj in many ways. He began to ____ his speaking skills and his confidence.","answer":"develop"},{"passageId":"u10_41_develop_passage_2","contextId":"u10_41_develop_gap_2","text":"The company spent three years on a new learning app. Engineers worked hard to ____ it before it was launched.","answer":"develop"}],"contextDependentParaphrases":[],"wrongParaphrases":["shrink","stay the same","lose"],"misleadingDistractors":["to make something smaller and weaker","to stop something from changing","to lose a skill through not using it"],"teacherNote":"Verb: to grow or improve, or to make something grow or improve (develop a skill, develop into, develop an idea); also to create something new (develop a product). Common spelling error: *developpe / *develope. The noun development and the adjective developed are taught in the Word Family pathway."}]'::jsonb,'["development","developed"]'::jsonb,'["develop a skill","develop an idea","develop into"]'::jsonb,'live'),
('vocab_communicate_10','communicate','verb','to share information, ideas or feelings with someone by speaking, writing or other ways','[{"senseId":"communicate_10_1","meaning":"to share information, ideas or feelings with someone by speaking, writing or other ways","acceptedParaphrases":["share ideas","exchange information"],"masteryContexts":[{"contextId":"u10_42_communicate_10_meaning","text":"Overseas students quickly learn to communicate in English with their classmates.","meaning":"to share ideas by speaking a language","wrongMeanings":["to keep ideas to yourself","to translate ideas into writing","to compete with others"]},{"contextId":"u10_42_communicate_10_paraphrase","text":"A good presentation should communicate one main message to the audience.","meaning":"to make an idea clear to other people","wrongMeanings":["to hide an idea from people","to repeat many different ideas","to change an idea completely"]}],"situationDistractors":["A boy kept his test result secret from his family.","A parrot repeated the same word over and over.","Two neighbours shouted angrily about a fence.","A boy kept his worries to himself.","A girl wore headphones and ignored everyone.","A student refused to answer any questions."],"gapDistractors":[{"contextId":"u10_42_communicate_10_gap_1","answer":"communicate","wrong":["succeed","reflect","evaluate"]},{"contextId":"u10_42_communicate_10_gap_2","answer":"communicate","wrong":["succeed","reflect","evaluate"]},{"contextId":"u10_42_communicate_10_gap_3","answer":"communicate","wrong":["succeed","evaluate","reflect"]}],"spellingErrors":["comunicate","communcate","communikate","comunnicate","communicat","comminicate"],"wordFamilyForms":[{"form":"communicate","partOfSpeech":"verb","example":"We communicate with our partner school by email.","pedagogicallyUseful":true},{"form":"communication","partOfSpeech":"noun","example":"Good communication is essential in a team.","pedagogicallyUseful":true,"altExample":"The storm cut off all communication with the island."},{"form":"communicative","partOfSpeech":"adjective","example":"Our teacher uses a communicative approach with lots of speaking.","pedagogicallyUseful":true,"altExample":"The test measures how communicative you are in English."}],"masteryPassages":[{"passageId":"u10_42_communicate_10_passage_1","contextId":"u10_42_communicate_10_gap_1","text":"Sara could not speak the local language when she arrived. At first, she used gestures and pictures to ____ with her neighbours.","answer":"communicate"},{"passageId":"u10_42_communicate_10_passage_2","contextId":"u10_42_communicate_10_gap_2","text":"A good poster has one clear message. It should ____ that message to anyone who walks past.","answer":"communicate"}],"contextDependentParaphrases":[],"wrongParaphrases":["hide information","repeat words","argue loudly"],"misleadingDistractors":["to keep information secret from others","to repeat the same words again and again","to argue loudly with someone"],"teacherNote":"Verb: to share information, ideas or feelings (communicate with someone, communicate in English, communicate an idea). Unit 10 uses it for speaking and presentation skills; Unit 2 taught it for digital life. The noun communication and the adjective communicative are taught in the Word Family pathway."}]'::jsonb,'["communication","communicative"]'::jsonb,'["communicate with","communicate clearly","communicate an idea"]'::jsonb,'live'),
('vocab_opinion','opinion','noun','what a person thinks or believes about something','[{"senseId":"opinion_1","meaning":"what a person thinks or believes about something","acceptedParaphrases":["view","personal belief"],"masteryContexts":[{"contextId":"u10_43_opinion_meaning","text":"The teacher asked each student to give their opinion about the book.","meaning":"what someone thinks about something","wrongMeanings":["a fact that can be checked","a summary of the story","a list of characters"]},{"contextId":"u10_43_opinion_paraphrase","text":"Public opinion has turned against the plan to close the library.","meaning":"what most people in a society think","wrongMeanings":["the laws of a country","the money a country spends","the leaders of a country"]}],"situationDistractors":["A student wrote that water boils at one hundred degrees.","The government published a new law about driving.","A maths question asked what seven times eight is.","A student measured the length of a table.","A teacher wrote the date on the board.","A boy looked up the capital of France."],"gapDistractors":[{"contextId":"u10_43_opinion_gap_1","answer":"opinion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_43_opinion_gap_2","answer":"opinion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_43_opinion_gap_3","answer":"opinion","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["oppinion","opinon","opinnion","opineon","opion","oppinon"],"masteryPassages":[{"passageId":"u10_43_opinion_passage_1","contextId":"u10_43_opinion_gap_1","text":"Some people think homework is useful, but others disagree. In my ____, a small amount of homework helps students remember what they learn.","answer":"opinion"},{"passageId":"u10_43_opinion_passage_2","contextId":"u10_43_opinion_gap_2","text":"The teacher asked each student what they thought of the novel. Most students gave a positive ____.","answer":"opinion"}],"contextDependentParaphrases":[],"wrongParaphrases":["fact","law","calculation"],"misleadingDistractors":["a fact that everyone agrees is true","a rule written by the government","a question with only one correct answer"],"teacherNote":"Noun: what someone thinks about something (in my opinion, give / express your opinion, a strong opinion, public opinion). Countable. Boundary: an opinion is a personal belief; a fact can be checked. Useful phrases for Paper 2 opinion writing: In my opinion, ...; Some people are of the opinion that ..."}]'::jsonb,'[]'::jsonb,'["in my opinion","give your opinion","public opinion"]'::jsonb,'live'),
('vocab_preference_10','preference','noun','a feeling of liking one thing more than another, or the thing you like more','[{"senseId":"preference_10_1","meaning":"a feeling of liking one thing more than another, or the thing you like more","acceptedParaphrases":["choice","the thing you like better"],"masteryContexts":[{"contextId":"u10_44_preference_10_meaning","text":"Students can choose online or classroom lessons, depending on their preference.","meaning":"what someone likes or wants more","wrongMeanings":["what someone is forced to do","what someone cannot afford","what someone has forgotten"]},{"contextId":"u10_44_preference_10_paraphrase","text":"Many employers show a preference for applicants with work experience.","meaning":"a tendency to choose one thing rather than another","wrongMeanings":["a refusal to choose anyone","a rule against choosing someone","a fear of choosing wrongly"]}],"situationDistractors":["A student had to attend a lesson she did not want to go to.","A boy had never tried sushi before.","A girl forgot which film she had watched last week.","A boy had to wear the uniform he was given.","A girl ate the only meal on offer.","A student was placed in a class without being asked."],"gapDistractors":[{"contextId":"u10_44_preference_10_gap_1","answer":"preference","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_44_preference_10_gap_2","answer":"preference","wrong":["loneliness","literacy","intonation"]},{"contextId":"u10_44_preference_10_gap_3","answer":"preference","wrong":["loneliness","literacy","intonation"]}],"spellingErrors":["preferance","prefrence","prefference","preferrence","prefernce","preferense"],"wordFamilyForms":[{"form":"preference","partOfSpeech":"noun","example":"Do you have a preference for morning or afternoon classes?","pedagogicallyUseful":true},{"form":"prefer","partOfSpeech":"verb","example":"Most students prefer group work to working alone.","pedagogicallyUseful":true,"altExample":"I prefer studying in the library to studying at home."},{"form":"preferable","partOfSpeech":"adjective","example":"A short walk is preferable to a long bus ride.","pedagogicallyUseful":true,"altExample":"For most students, a quiet room is preferable to a busy café."}],"masteryPassages":[{"passageId":"u10_44_preference_10_passage_1","contextId":"u10_44_preference_10_gap_1","text":"You can choose to sit the test on paper or on a computer. Please tell your teacher your ____ by Friday.","answer":"preference"},{"passageId":"u10_44_preference_10_passage_2","contextId":"u10_44_preference_10_gap_2","text":"Many employers choose candidates who have already worked in the industry. They show a clear ____ for experience.","answer":"preference"}],"contextDependentParaphrases":[],"wrongParaphrases":["obligation","novelty","memory"],"misleadingDistractors":["a thing you are forced to do","a thing you have never tried","a thing you have forgotten"],"teacherNote":"Noun: liking one thing more than another (a preference for, have no preference, personal preference). Countable. Unit 10 uses it for learning styles and courses; Unit 1 taught it for free-time choices. The verb prefer and the adjective preferable are taught in the Word Family pathway; note the double r in preferred but not in preference."}]'::jsonb,'["prefer","preferable"]'::jsonb,'["a preference for","have no preference","personal preference"]'::jsonb,'live'),
('vocab_discussion','discussion','noun','a conversation in which people talk about a subject and share their ideas and opinions','[{"senseId":"discussion_1","meaning":"a conversation in which people talk about a subject and share their ideas and opinions","acceptedParaphrases":["talk","exchange of views"],"masteryContexts":[{"contextId":"u10_45_discussion_meaning","text":"The teacher divided us into groups for a discussion about climate change.","meaning":"a talk in which people share ideas","wrongMeanings":["a speech given by one person","a test taken in silence","a game played in teams"]},{"contextId":"u10_45_discussion_paraphrase","text":"The new uniform policy is still under discussion, so nothing has been decided.","meaning":"the process of being talked about before a decision","wrongMeanings":["the process of being cancelled","the process of being advertised","the process of being forgotten"]}],"situationDistractors":["A famous author gave a speech and left without answering questions.","Students sat a reading test in silence.","Two boys started pushing each other in the corridor.","A teacher read out a notice and left.","A boy worked silently on his own.","Two girls ignored each other all day."],"gapDistractors":[{"contextId":"u10_45_discussion_gap_1","answer":"discussion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_45_discussion_gap_2","answer":"discussion","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_45_discussion_gap_3","answer":"discussion","wrong":["loneliness","literacy","recreation"]}],"spellingErrors":["discusion","disscussion","discution","discussoin","diskussion","discusssion"],"masteryPassages":[{"passageId":"u10_45_discussion_passage_1","contextId":"u10_45_discussion_gap_1","text":"Our class talked for an hour about whether phones should be banned at school. It was a lively ____, and everyone shared their views.","answer":"discussion"},{"passageId":"u10_45_discussion_passage_2","contextId":"u10_45_discussion_gap_2","text":"The council has not decided whether to close the library. The plan is still under ____.","answer":"discussion"}],"contextDependentParaphrases":[],"wrongParaphrases":["speech","silence","fight"],"misleadingDistractors":["a speech given by one person with no questions","a written test in silence","an argument that ends in a fight"],"teacherNote":"Noun: a conversation in which people share ideas about a subject (have a discussion about, a class discussion, under discussion). Countable. Boundary: a discussion is an exchange of views; an argument suggests disagreement and strong feelings. The verb discuss (discuss something, not *discuss about) is taught in the Word Family pathway."}]'::jsonb,'[]'::jsonb,'["a class discussion","have a discussion about","under discussion"]'::jsonb,'live'),
('vocab_achievement_10','achievement','noun','something good and difficult that you have done successfully through effort or skill','[{"senseId":"achievement_10_1","meaning":"something good and difficult that you have done successfully through effort or skill","acceptedParaphrases":["accomplishment","success"],"masteryContexts":[{"contextId":"u10_46_achievement_10_meaning","text":"Learning to read at the age of seventy was an amazing achievement.","meaning":"something difficult done successfully","wrongMeanings":["something that happened by luck","something easy that anyone can do","something that went badly wrong"]},{"contextId":"u10_46_achievement_10_paraphrase","text":"The school celebrates academic achievement with a prize-giving every June.","meaning":"success in study gained through effort","wrongMeanings":["failure that is hidden from others","money spent on students","luck that comes without effort"]}],"situationDistractors":["A boy failed a test because he forgot to turn the page.","A girl had not yet started the project that was due tomorrow.","A student found some money in the street.","A boy lost his keys on the way home.","A girl gave up after the first try.","A student was given a free ticket by chance."],"gapDistractors":[{"contextId":"u10_46_achievement_10_gap_1","answer":"achievement","wrong":["loneliness","literacy","recreation"]},{"contextId":"u10_46_achievement_10_gap_2","answer":"achievement","wrong":["loneliness","literacy","intonation"]},{"contextId":"u10_46_achievement_10_gap_3","answer":"achievement","wrong":["loneliness","pronunciation","recreation"]}],"spellingErrors":["acheivement","achievment","achievemant","acheivment","achivement","achievemnet"],"wordFamilyForms":[{"form":"achievement","partOfSpeech":"noun","example":"Passing the exam was a great achievement.","pedagogicallyUseful":true},{"form":"achieve","partOfSpeech":"verb","example":"She worked hard to achieve her goals.","pedagogicallyUseful":true,"altExample":"You can achieve a lot in ten minutes a day."},{"form":"achievable","partOfSpeech":"adjective","example":"Set yourself small, achievable targets each week.","pedagogicallyUseful":true,"altExample":"The coach set an achievable goal for the season."}],"masteryPassages":[{"passageId":"u10_46_achievement_10_passage_1","contextId":"u10_46_achievement_10_gap_1","text":"Nadia failed maths twice but never gave up. Passing it with a top grade was her greatest ____.","answer":"achievement"},{"passageId":"u10_46_achievement_10_passage_2","contextId":"u10_46_achievement_10_gap_2","text":"Every June, the school holds a ceremony. Students receive prizes for academic ____ and for helping others.","answer":"achievement"}],"contextDependentParaphrases":[],"wrongParaphrases":["failure","mistake","gift"],"misleadingDistractors":["a mistake made because of carelessness","a task that has not been started","a gift received without effort"],"teacherNote":"Noun: something good done successfully through effort (a great / major achievement, a sense of achievement, academic achievement). Countable and uncountable. Unit 10 uses it for academic success; Units 1 and 6 taught it for sport and study. Spelling: i before e (achieve). The verb achieve is taught in the Word Family pathway."}]'::jsonb,'["achieve","achievable"]'::jsonb,'["a great achievement","a sense of achievement","academic achievement"]'::jsonb,'live'),
('vocab_qualification_10','qualification','noun','an official record, such as a certificate or degree, showing that you have passed exams or completed a course','[{"senseId":"qualification_10_1","meaning":"an official record, such as a certificate or degree, showing that you have passed exams or completed a course","acceptedParaphrases":["certificate","official record of a completed course"],"masteryContexts":[{"contextId":"u10_47_qualification_10_meaning","text":"IGCSEs are an international qualification recognised by universities around the world.","meaning":"an official record of passing exams","wrongMeanings":["a holiday destination for students","a type of school uniform","a sports competition"]},{"contextId":"u10_47_qualification_10_paraphrase","text":"Without the right qualification, he could not apply for the nursing course.","meaning":"a certificate needed to do something","wrongMeanings":["a reference from a friend","a list of hobbies","a photo of the applicant"]}],"situationDistractors":["A student read a list of part-time jobs in the newspaper.","A friend wrote a kind note about a boy’s character.","A teacher printed the school calendar for next year.","A boy read a poster about a school disco.","A girl wrote a shopping list.","A student looked at the lunch menu."],"gapDistractors":[{"contextId":"u10_47_qualification_10_gap_1","answer":"qualification","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_47_qualification_10_gap_2","answer":"qualification","wrong":["loneliness","recreation","intonation"]},{"contextId":"u10_47_qualification_10_gap_3","answer":"qualification","wrong":["loneliness","recreation","intonation"]}],"spellingErrors":["qualifiation","qualifcation","qualificashion","quallification","qualificaton","qualafication"],"wordFamilyForms":[{"form":"qualification","partOfSpeech":"noun","example":"A degree is a useful qualification.","pedagogicallyUseful":true},{"form":"qualify","partOfSpeech":"verb","example":"She hopes to qualify as a nurse next year.","pedagogicallyUseful":true,"altExample":"Students who pass the course qualify for a certificate."},{"form":"qualified","partOfSpeech":"adjective","example":"Only qualified teachers can work at the school.","pedagogicallyUseful":true,"altExample":"The school is looking for a qualified music teacher."}],"masteryPassages":[{"passageId":"u10_47_qualification_10_passage_1","contextId":"u10_47_qualification_10_gap_1","text":"To work as a nurse, you must complete a three-year course. Without this ____, hospitals will not employ you.","answer":"qualification"},{"passageId":"u10_47_qualification_10_passage_2","contextId":"u10_47_qualification_10_gap_2","text":"IGCSEs are recognised by universities all over the world. They are a valuable ____ for students who want to study abroad.","answer":"qualification"}],"contextDependentParaphrases":[],"wrongParaphrases":["job advert","personal note","school calendar"],"misleadingDistractors":["a list of jobs that are available","a reference written by a friend","a timetable for the school year"],"teacherNote":"Noun: an exam pass, certificate or degree that shows your level (a qualification in, academic / professional qualifications, gain a qualification). Countable. Unit 10 uses it for school leaving and higher education; Units 5 and 7 taught it for jobs and interviews. The verb qualify and the adjective qualified are taught in the Word Family pathway."}]'::jsonb,'["qualify","qualified"]'::jsonb,'["a qualification in","academic qualifications","gain a qualification"]'::jsonb,'live'),
('vocab_succeed','succeed','verb','to achieve something that you have been trying to do','[{"senseId":"succeed_1","meaning":"to achieve something that you have been trying to do","acceptedParaphrases":["do well","achieve your aim"],"masteryContexts":[{"contextId":"u10_48_succeed_meaning","text":"After three attempts, she hopes to succeed in her driving test this time.","meaning":"to manage to do something difficult","wrongMeanings":["to give up trying","to forget to try","to try for the first time"]},{"contextId":"u10_48_succeed_paraphrase","text":"The school helps every student succeed, whatever their background.","meaning":"to do well in study or life","wrongMeanings":["to fail in study or life","to leave school early","to move to another school"]}],"situationDistractors":["A boy stopped running halfway through the race.","A girl tried ice skating for the very first time.","A student sent the wrong file to her teacher.","A girl dropped out of the race halfway.","A boy’s plan to build a raft sank immediately.","A student failed the test for the third time."],"gapDistractors":[{"contextId":"u10_48_succeed_gap_1","answer":"succeed","wrong":["encourage","evaluate","communicate"]},{"contextId":"u10_48_succeed_gap_2","answer":"succeed","wrong":["encourage","evaluate","develop"]},{"contextId":"u10_48_succeed_gap_3","answer":"succeed","wrong":["encourage","evaluate","reflect"]}],"spellingErrors":["succed","suceed","sucseed","succeeed","succede","sucede"],"wordFamilyForms":[{"form":"succeed","partOfSpeech":"verb","example":"With hard work, you will succeed.","pedagogicallyUseful":true},{"form":"success","partOfSpeech":"noun","example":"The concert was a great success.","pedagogicallyUseful":true,"altExample":"Her success in the competition made the newspapers."},{"form":"successful","partOfSpeech":"adjective","example":"He runs a successful business in the city.","pedagogicallyUseful":true,"altExample":"The fundraising event was very successful."}],"masteryPassages":[{"passageId":"u10_48_succeed_passage_1","contextId":"u10_48_succeed_gap_1","text":"Climbing the mountain took three attempts. On the third try, the team finally managed to ____.","answer":"succeed"},{"passageId":"u10_48_succeed_passage_2","contextId":"u10_48_succeed_gap_2","text":"The new mentoring scheme gives every student support. Its aim is to help everyone ____, whatever their background.","answer":"succeed"}],"contextDependentParaphrases":[],"wrongParaphrases":["give up","start out","go wrong"],"misleadingDistractors":["to give up before the end","to try something for the first time","to make a serious mistake"],"teacherNote":"Verb: to achieve what you have been trying to do (succeed in doing something, succeed at school, succeed in life). Pattern: succeed in + -ing (not *succeed to do). Common spelling error: *succed / *suceed. The noun success, the adjective successful and the adverb successfully are taught in the Word Family pathway."}]'::jsonb,'["success","successful"]'::jsonb,'["succeed in","succeed at school","help someone succeed"]'::jsonb,'live')
